/**
 * Imagens de fora (todas de uso livre).
 * - Grama: "Seamless grass texture II" de athile, OpenGameArt, licença CC0
 *   (https://opengameart.org/content/seamless-grass-texture-ii). Reduzida para 256 px e com menos saturação.
 * - Dragão e soldados: sprites em pixel art enviados pelo Agostinho (arquivos em arte/).
 *   Recortados, fundo tirado e cores das Casas trocadas no código. Conferir a licença/autor antes de publicar.
 */
export const DRAGON_PNG = "data:image/png;base64,";
export const SOLDIERS_PNG = "data:image/png;base64,";
export const GRASS_JPG = "data:image/jpeg;base64,";

const images: Record<string, HTMLImageElement> = {};
let ready = false;
let loading: Promise<void> | null = null;

/** Carrega as imagens; o campo é repintado quando elas chegam. */
export function loadAssets(): Promise<void> {
  if (loading) return loading;
  const load = (key: string, src: string): Promise<void> => {
    const img = new Image();
    img.src = src;
    images[key] = img;
    return img.decode().then(
      () => undefined,
      () => undefined
    );
  };
  loading = Promise.all([load("grass", GRASS_JPG), load("dragon", DRAGON_PNG), load("soldiers", SOLDIERS_PNG)]).then(() => {
    ready = true;
  });
  return loading;
}

export function assetsReady(): boolean {
  return ready;
}

export function grassImage(): HTMLImageElement | null {
  return ready ? images.grass : null;
}

export function dragonImage(): HTMLImageElement | null {
  return ready ? images.dragon : null;
}

export function soldiersImage(): HTMLImageElement | null {
  return ready ? images.soldiers : null;
}
